import React from 'react';

const Footer = ({ data }) => {
  const name = data?.personalInfo?.name || 'Maithily M. Gondode';
  const year = new Date().getFullYear();

  return (
    <footer style={{
      borderTop:'1px solid rgba(232,121,154,0.12)',
      padding:'2.5rem 2rem',
      textAlign:'center',
      position:'relative', zIndex:1,
    }}>
      {/* Decorative petal */}
      <div style={{ fontSize:'1.5rem', marginBottom:'0.75rem', opacity:0.5 }}>🌸</div>

      <div style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.1rem', fontWeight:600, color:'rgba(253,240,244,0.5)', marginBottom:'0.5rem' }}>
        Crafted with 💕 by <span style={{ background:'linear-gradient(135deg,#e8799a,#b882d4)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent' }}>{name}</span>
      </div>
      <div style={{ fontFamily:"'DM Mono', monospace", fontSize:'0.72rem', color:'rgba(253,240,244,0.3)', letterSpacing:'0.1em' }}>
        © {year} · Built with React
      </div>
    </footer>
  );
};

export default Footer;
